#nullable enable

using Campaigns.Contracts;
using Campaigns.Views;
using Marten;
using Shouldly;
using Xunit;

namespace Campaigns.IntegrationTests.Slices.Campaigns;

/// <summary>
/// Generated from the model's GIVEN/THEN cells, NOT from the implementation. Pattern: view. Status: ready.
/// Owned by backend-agent. No WHEN: a read model only reads events that already exist.
///
/// WHAT THESE GTs PIN DOWN: <c>identity="senderId, month"</c>. One row collects one event each from an
/// unbounded number of Message streams, so the two halves of the grain need asserting separately —
/// a rollup must COMBINE (test 1) and SEPARATE (test 2), and a projection that put every message in the
/// world on one row satisfies the first on its own.
///
/// This view is a <c>MultiStreamProjection</c> registered <c>Inline</c>, against Marten's default of Async
/// for that recipe — so unlike CampaignDashboardTests next door, nothing here waits. The two are the same
/// recipe with different lifecycles on purpose; the cost of each is visible as the presence or absence of a
/// wait in these files.
/// </summary>
public sealed class SenderMonthlyTests(AppFixture fixture) : IntegrationContext(fixture)
{
    // Two fixed senders, so "two rows" names its rows rather than inventing them per run.
    private static readonly Guid SenderA = Guid.Parse("55555555-5555-5555-5555-555555555555");
    private static readonly Guid SenderB = Guid.Parse("66666666-6666-6666-6666-666666666666");

    private static readonly Guid SecondMessageId = Guid.Parse("77777777-7777-7777-7777-777777777777");
    private static readonly Guid ThirdMessageId = Guid.Parse("88888888-8888-8888-8888-888888888888");

    /// <summary>One message on its own stream. A row of this view spans many of these.</summary>
    private Task Queued(Guid messageId, Guid senderId, params string[] recipients) =>
        Given(messageId, new MessageQueued(
            messageId, SeedData.CampaignId, senderId, "January newsletter", recipients, SeedData.SeededAt));

    /// <summary>
    /// Fetched BY SENDER rather than by id, deliberately. Loading by <c>Key(sender, DateTimeOffset.UtcNow)</c>
    /// would bake this test's own idea of the month into the lookup, and the month is exactly what the view
    /// derives — so a row filed under the wrong month would read as a missing row. Querying by the field the
    /// event does carry lets the assertions state which month it landed in.
    /// </summary>
    private async Task<List<SenderMonthly>> RowsFor(Guid senderId)
    {
        await using var session = Store.QuerySession();
        var rows = await session.Query<SenderMonthly>().Where(x => x.SenderId == senderId).ToListAsync();
        return rows.OrderBy(r => r.Month, StringComparer.Ordinal).ToList();
    }

    private async Task<List<SenderMonthly>> AllRows()
    {
        await using var session = Store.QuerySession();
        var rows = await session.Query<SenderMonthly>().ToListAsync();
        return rows.OrderBy(r => r.Id, StringComparer.Ordinal).ToList();
    }

    // one sender's month rolls up across messages
    //   GIVEN MessageQueued, MessageQueued
    //   THEN  SenderMonthly
    [Fact]
    public async Task OneSenderSMonthRollsUpAcrossMessages()
    {
        // Captured before the append, because the month this row is filed under is the month the events were
        // APPENDED in — IEvent.Timestamp, stamped by Marten, ignoring queuedAt in the payload entirely. See
        // finding #1 in the folder README: that is a trap this file demonstrates rather than avoids.
        var appendedAt = DateTimeOffset.UtcNow;

        await Queued(SeedData.MessageId, SenderA, "a@example.com", "b@example.com");
        await Queued(SecondMessageId, SenderA, "c@example.com");

        var rows = await RowsFor(SenderA);

        // TWO STREAMS, ONE ROW. The combining half of the grain.
        rows.Count.ShouldBe(1);
        var row = rows.Single();

        row.SenderId.ShouldBe(SenderA);
        row.Messages.ShouldBe(2);        // derived: a COUNT of events, carried by nothing
        row.Recipients.ShouldBe(3);      // derived: 2 + 1, summed across streams

        // The month, and the composite id built from both halves of identity=. Asserting Id against the row's
        // OWN month rather than against a formatted clock reading keeps this from failing at a month boundary
        // while still checking that the id is the pairing.
        row.Month.ShouldBe($"{appendedAt:yyyy-MM}");
        row.Id.ShouldBe($"{SenderA}:{row.Month}");
        row.Id.ShouldBe(SenderMonthlyProjection.Key(SenderA, appendedAt));
    }

    // two senders are two rows
    //   GIVEN MessageQueued, MessageQueued
    //   THEN  SenderMonthly
    [Fact]
    public async Task TwoSendersAreTwoRows()
    {
        await Queued(SeedData.MessageId, SenderA, "a@example.com");
        await Queued(SecondMessageId, SenderB, "b@example.com");
        await Queued(ThirdMessageId, SenderB, "c@example.com", "d@example.com");

        // THE SEPARATING HALF OF THE GRAIN, and the reason this GT exists: a grouping keyed on the wrong
        // field — the campaign, the month alone, the stream — passes the previous test and fails here,
        // because there the answer was one row either way.
        (await AllRows()).Count.ShouldBe(2);

        var a = (await RowsFor(SenderA)).Single();
        var b = (await RowsFor(SenderB)).Single();

        a.Messages.ShouldBe(1);
        a.Recipients.ShouldBe(1);

        b.Messages.ShouldBe(2);
        b.Recipients.ShouldBe(3);

        // Neither row absorbed the other's events: 1 + 2 is the total, and each row's id names its own sender.
        a.Id.ShouldNotBe(b.Id);
        a.Id.ShouldStartWith(SenderA.ToString());
        b.Id.ShouldStartWith(SenderB.ToString());
    }

    // an outcome does not touch the monthly rollup
    //   GIVEN MessageQueued, MessageDelivered
    //   THEN  SenderMonthly
    [Fact]
    public async Task AnOutcomeDoesNotTouchTheMonthlyRollup()
    {
        var messageId = SeedData.MessageId;
        await Queued(messageId, SenderA, "a@example.com", "b@example.com");

        // The BEFORE, and the WHOLE table rather than one row — so that a reaction which invented a new row
        // is caught as well as one that changed this row. Either would be a view reacting to an event the
        // drawing does not connect to it.
        var before = await AllRows();
        before.Count.ShouldBe(1);
        before.Single().Messages.ShouldBe(1);

        await Given(messageId, new MessageDelivered(messageId, "a@example.com", SeedData.SeededAt));

        // The ignored event really is in the store. Without this the test would pass just as well against a
        // GIVEN that never landed, which is the standing hazard of asserting that nothing happened.
        (await EventsFor(messageId)).Length.ShouldBe(2);

        // ONLY MessageQueued FEEDS THIS VIEW — one arrow on the drawing, and this is the only place that
        // claim is executable. SenderMonthly is a rollup of messages SENT, not of outcomes; a fold that also
        // counted deliveries would inflate every monthly report by a number nobody could trace, and no other
        // test in this project would notice.
        (await AllRows()).ShouldBe(before);
    }
}
